import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        String s = new Scanner(System.in).next();
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) sb.append((char) ('A' + (c - 'A' + 4) % 26)); // shift right by 4, wrapping
        System.out.println(sb);
    }
}

package main

import "fmt"

func main() {
	var s string
	fmt.Scan(&s)
	b := []byte(s)
	for i, c := range b {
		b[i] = 'A' + (c-'A'+4)%26 // shift right by 4, wrapping Z -> A
	}
	fmt.Println(string(b))
}
